INSERT INTO games (id, title, version, lifecycle, source_status, multiplayer_status, manifest_json) VALUES ('royal-ballistix', 'Royal Ballistix — Beach Siege', '0.12.0', 'experimental', 'imported', 'not-integrated', '{"id":"royal-ballistix","title":"Royal Ballistix — Beach Siege","aliases":["Royal Ballistix","Ballistix","Beach Siege","Royal Ballistix Beach Siege"],"tags":["physics","ball-deflection","survival","arcade","party","bots","mobile","canvas"],"description":"Radial ball-deflection survival game for 2–10 contestants. One local player can defend a gate with movement, Magnet, Pulse and Run while AI bots fill remaining seats; arena size is adjustable and phone/network transport is not yet integrated.","players":{"min":2,"max":10},"version":"0.12.0","source":{"status":"imported","paths":["source/index.html"],"provenance":"Imported unchanged from edmondsonedits/CALLBACK commit ed09d25b690b36b397516e4d77437e3dd21247c8 (game-modes/royal-ballistix/index.html). Upstream repository license: Apache-2.0.","url":"https://github.com/edmondsonedits/CALLBACK/blob/ed09d25b690b36b397516e4d77437e3dd21247c8/game-modes/royal-ballistix/index.html"},"lifecycle":"experimental","multiplayer":{"status":"not-integrated","evidence":[]}}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, version=excluded.version, lifecycle=excluded.lifecycle, source_status=excluded.source_status, multiplayer_status=excluded.multiplayer_status, manifest_json=excluded.manifest_json;
INSERT INTO games (id, title, version, lifecycle, source_status, multiplayer_status, manifest_json) VALUES ('royal-roller-ruckus', 'Royal Roller Ruckus', '1.4.0', 'experimental', 'imported', 'in-progress', '{"id":"royal-roller-ruckus","title":"Royal Roller Ruckus","aliases":["Roller Ruckus","Royal Roller Ruckus: Vertical Crownway"],"tags":["racing","physics","party","collision","bots","3d"],"description":"A 2–10 contestant rolling-cage physics race on the Vertical Crownway, with momentum handling, collisions, recoverable falls, elevation changes, Crownline boosts, rough terrain and bot-filled seats. Standalone source is imported; authenticated phone-room multiplayer transport is not yet implemented.","players":{"min":2,"max":10},"version":"1.4.0","source":{"status":"imported","paths":["source/index.html"],"provenance":"Imported from the complete Royal Roller Ruckus v1.4.0 — Vertical Crownway HTML produced in the user''s CALLBACK game-development chat. The exact chat build is preserved as source/original-v1.4.0.html. Visuals and prototype audio are procedural/inline; Three.js 0.180.0 is vendored separately under its MIT license.","url":null},"lifecycle":"experimental","multiplayer":{"status":"in-progress","evidence":["integration/README.md"]}}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, version=excluded.version, lifecycle=excluded.lifecycle, source_status=excluded.source_status, multiplayer_status=excluded.multiplayer_status, manifest_json=excluded.manifest_json;
INSERT INTO games (id, title, version, lifecycle, source_status, multiplayer_status, manifest_json) VALUES ('royal-scratch-match', 'Royal Scratch Match', '0.5.0', 'experimental', 'imported', 'not-integrated', '{"id":"royal-scratch-match","title":"Royal Scratch Match","aliases":["Scratch Match","Create Scratch Match"],"tags":["rhythm","music","timing","memory","arcade","bots","mobile"],"description":"Imported v0.5 standalone call-and-response rhythm game for 2–10 contestant slots. One local touch/keyboard player is supported by default, remaining slots can be bot-controlled, and additional human slots can receive inputs through the existing JavaScript API. Room-code phone multiplayer is not yet integrated.","players":{"min":2,"max":10},"version":"0.5.0","source":{"status":"imported","paths":["source/index.html"],"provenance":"Standalone royal_scratch_match_v0.5_ten_player.html created in the user''s ChatGPT CALLBACK project and supplied by the user in this chat for import. Imported without gameplay changes as source/index.html. The runtime has no external asset dependencies; the user explicitly requested this project/repository use.","url":null},"lifecycle":"experimental","multiplayer":{"status":"not-integrated","evidence":[]}}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, version=excluded.version, lifecycle=excluded.lifecycle, source_status=excluded.source_status, multiplayer_status=excluded.multiplayer_status, manifest_json=excluded.manifest_json;
INSERT INTO games (id, title, version, lifecycle, source_status, multiplayer_status, manifest_json) VALUES ('royal-sumo', 'Royal Sumo', '0.21.0', 'experimental', 'imported', 'in-progress', '{"id":"royal-sumo","title":"Royal Sumo","aliases":["Sumo","Royal Sumo Crownfall","Crownfall Arena"],"tags":["arena","physics","sumo","arcade","party","bots","three-js"],"description":"A 2–10 fighter shrinking-arena physics sumo game with Bash, Dash, stability, knockouts, dynamic camera work and bot-filled contestant slots. The standalone v0.21 source is imported; online phone-room transport is not yet implemented.","players":{"min":2,"max":10},"version":"0.21.0","controls":{"local":["virtual joystick","hold/release Bash","tap Dash","pause/settings"],"remoteHooks":["moveX/moveY","bashPressed/bashCharge","dashPressed","sequence"]},"source":{"status":"imported","paths":["source/index.html","source/original/royal_sumo_crownfall_v0.21_player_scaled_arena.html","source/vendor/three.module.js","source/vendor/three.core.js"],"provenance":"Royal Sumo/Crownfall Arena v0.21.0 was developed in the user''s ChatGPT CALLBACK project. The exact original HTML is retained under source/original/. The packaged entry replaces the pinned Three.js CDN import with the vendored r180 MIT build and updates the existing state snapshot when debug display is disabled. Gameplay tuning is preserved.","url":null},"lifecycle":"experimental","multiplayer":{"status":"in-progress","evidence":[]}}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, version=excluded.version, lifecycle=excluded.lifecycle, source_status=excluded.source_status, multiplayer_status=excluded.multiplayer_status, manifest_json=excluded.manifest_json;
INSERT INTO games (id, title, version, lifecycle, source_status, multiplayer_status, manifest_json) VALUES ('royal-twisted', 'Royal Twisted', '0.5.0', 'experimental', 'imported', 'not-integrated', '{"id":"royal-twisted","title":"Royal Twisted","aliases":["Spiral Keep","Twisted System-style"],"tags":["reaction","survival","obstacle-dodge","physics","arcade"],"description":"A 2–10 contestant reaction-survival game on a medieval spiral tower: jump low rods, duck high rods, survive seven strikes, and recover from hits that knock contestants back down the course. The standalone v0.5 source is imported with bots and local controls; phone-room multiplayer is not yet integrated.","players":{"min":2,"max":10},"version":"0.5.0","source":{"status":"imported","paths":["source/index.html"],"provenance":"Original Royal Twisted v0.5 HTML developed in the user''s ChatGPT CALLBACK project conversation and imported from the complete chat artifact. Gameplay implementation, visuals, UI, procedural audio and characters are original to this project. Three.js r180 is vendored under assets/vendor under its MIT license. The packaged entry changes only the Three.js import from a pinned jsDelivr URL to the vendored local module; gameplay logic is otherwise preserved.","url":null},"lifecycle":"experimental","multiplayer":{"status":"not-integrated","evidence":[]}}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, version=excluded.version, lifecycle=excluded.lifecycle, source_status=excluded.source_status, multiplayer_status=excluded.multiplayer_status, manifest_json=excluded.manifest_json;
INSERT INTO games (id, title, version, lifecycle, source_status, multiplayer_status, manifest_json) VALUES ('space-bash', 'Space Bash — Orbital Breakfloor', '1.13.1', 'experimental', 'imported', 'not-integrated', '{"id":"space-bash","title":"Space Bash — Orbital Breakfloor","aliases":["Space Bash","Orbital Breakfloor"],"tags":["arena","physics","survival","destructible-floor","bots","arcade"],"description":"A self-contained 2–10 contestant physics survival arena with throwable crates, TNT/Nitro, destructible floor tiles, mobile multi-touch controls and bot-filled solo play. Source is imported; phone room-code multiplayer is not integrated.","players":{"min":2,"max":10},"version":"1.13.1","source":{"status":"imported","paths":["source/index.html"],"provenance":"User-directed original standalone HTML implementation developed in this ChatGPT project. The imported v1.13.1 build is self-contained Canvas 2D/JavaScript with procedural visuals and audio; no third-party game code, artwork, music, or binary assets are included.","url":null},"lifecycle":"experimental","multiplayer":{"status":"not-integrated","evidence":[]}}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, version=excluded.version, lifecycle=excluded.lifecycle, source_status=excluded.source_status, multiplayer_status=excluded.multiplayer_status, manifest_json=excluded.manifest_json;
